#include "beatglass/library/analysis_commit.hpp"
#include <exception>
namespace beatglass::library {
bool reuse_cached_operation(library_detail::SqliteCache& cache, const AnalysisIdentity& identity, std::string& result) {
    return cache.find({identity.content_hash, identity.engine_version, identity.configuration_id, identity.mode}, result);
}
library_detail::Publish publish_operation(library_detail::SqliteCache& cache,const std::string& id,const AnalysisOperation& op,std::stop_token stop){ if(id.empty()||!op.valid()) return library_detail::Publish::error; library_detail::CacheKey key{op.identity.content_hash,op.identity.engine_version,op.identity.configuration_id,op.identity.mode}; auto recover=[&]{ try { cache.mark_retryable(id,key); } catch (...) {} }; if(stop.stop_requested()) { recover(); return library_detail::Publish::cancelled; } auto verifier=[&]{return op.verify(stop).outcome==FileVerificationOutcome::match;}; try { auto result = op.decode ? op.decode(stop, [](std::uint64_t) {}) : op.serialize(); if(stop.stop_requested()) { recover(); return library_detail::Publish::cancelled; } return cache.publish(id,key,std::move(result),stop,verifier); } catch (...) { recover(); return library_detail::Publish::error; } }
std::function<bool(const std::string&, std::stop_token)> make_transactional_publisher(library_detail::SqliteCache& cache, std::string run_id, AnalysisIdentity identity, std::function<FileVerificationResult(std::stop_token)> verify) { return [&cache, run_id = std::move(run_id), identity = std::move(identity), verify = std::move(verify)](const std::string& result, std::stop_token stop) { if (run_id.empty() || stop.stop_requested()) return false; library_detail::CacheKey key{identity.content_hash, identity.engine_version, identity.configuration_id, identity.mode}; auto revalidate = [&] { return verify && verify(stop).outcome == FileVerificationOutcome::match; }; return cache.publish(run_id, key, result, stop, revalidate) == library_detail::Publish::committed; }; }
}
